const enfermedadData=[{"disease":"La cuota era baja y al final se devolvió casi el doble de lo prestado","characteristic":"No se sumó el costo total, solo se miró la cuota","opts":["No se sumó el costo total, solo se miró la cuota","La tasa subió a mitad de camino","Se pagó tarde varias veces","El préstamo era muy grande"]},{"disease":"Dos ofertas al mismo 2% y una costó 1.320 lempiras más","characteristic":"No se preguntó si el interés era sobre saldos o sobre el monto","opts":["No se preguntó si el interés era sobre saldos o sobre el monto","Una financiera cobró más comisiones","El plazo era distinto","La segunda pidió fiador"]},{"disease":"Aprobaron 20.000 y no alcanzó para comprar lo que se iba a comprar","characteristic":"No se preguntó cuánto llegaba a la cuenta después de los descuentos","opts":["No se preguntó cuánto llegaba a la cuenta después de los descuentos","El equipo subió de precio","Se gastó en otra cosa","El banco tardó en desembolsar"]},{"disease":"La cuota se pagaba puntual y aun así el mes no cerraba","characteristic":"No se rehizo el punto de equilibrio con la cuota como costo fijo","opts":["No se rehizo el punto de equilibrio con la cuota como costo fijo","Los ingresos bajaron sin aviso","Se cobró poco por aula","Subió el precio del dominio"]},{"disease":"Tres meses de atraso convirtieron 3.720 en cerca de 4.570","characteristic":"No se avisó ni se pidió reprogramar antes del vencimiento","opts":["No se avisó ni se pidió reprogramar antes del vencimiento","El contrato cambió de condiciones","Se perdió el recibo","El cobrador no pasó"]},{"disease":"La refinanciación alivió el mes y a los seis meses todo seguía igual","characteristic":"Se compró tiempo sin usarlo para cambiar la situación","opts":["Se compró tiempo sin usarlo para cambiar la situación","La nueva tasa era más alta","No se leyó la letra pequeña","Se cambió de financiera"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

