function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Una tienda ofrece la laptop de trabajo en 24 cuotas de 1.150 lempiras, «sin intereses». No aparece por ningún lado el precio de contado, que en otra tienda es de 20.000."},{"txt":"Hacen falta 12.000 lempiras para el equipo de grabación. Dos prestamistas ofrecen 2% mensual a doce meses: uno cobra sobre saldos y el otro sobre el monto. La primera cuota es 1.240 en los dos casos."},{"txt":"Un préstamo de 12.000 a doce meses deja una cuota de 1.240 al mes. Los fijos de M.E.T.A.S son hoy 750, el margen por aula es de 100 y hay seis aulas pagando."},{"txt":"Aprueban 20.000 lempiras. Del desembolso descuentan 3% de comisión, 400 de seguro de deuda y 250 de gastos, pero los intereses se calculan sobre los 20.000."},{"txt":"Dos préstamos iguales de 15.000: uno compra una laptop que permite producir dos misiones más al mes; el otro cubre un mes en que no alcanzó para los fijos."},{"txt":"Un mes malo y la cuota de 1.240 no se paga. El contrato dice 200 lempiras de recargo por cuota vencida y 5% mensual sobre lo vencido. Ya van tres meses."},{"txt":"A mitad del préstamo ofrecen bajar la cuota de 1.240 a 740 pasando el plazo de doce a veinticuatro meses, «para que respire»."},{"txt":"Un negocio ofrece adelantar 10.000 lempiras hoy a cambio de que su logo esté en las fichas dos años en vez de uno. No hay contrato de préstamo, ni tasa, ni cuota."}];
const critCaseQuestions=["1. ¿Qué falta preguntar en la oferta tal como está planteada?","2. Calcula el costo total en lempiras, o lo que de verdad se recibe.","3. ¿Qué le pasa al punto de equilibrio del proyecto si esto se firma?","4. Escribe en 3-4 frases qué decidirías y con qué condición por escrito."];
const critCaseGuides=["Lo que casi siempre falta es el precio de contado, si la tasa es sobre saldos o sobre el monto, cuánto llega de verdad a la cuenta y qué pasa si un mes no se paga. Y falta el cuadro de amortización, que nadie niega cuando se pide.","La cuenta se hace con el juego de números de la casa: préstamo de 12.000 a doce meses, 1.560 de intereses sobre saldos contra 2.880 sobre el monto, primera cuota de 1.240 en los dos, y 18.750 que llegan de 20.000 aprobados.","Toda cuota es un costo fijo nuevo. Con los fijos en 750 y el margen por aula en 100, el equilibrio son ocho aulas; con una cuota de 1.240, los fijos son 1.990 y el equilibrio salta a veinte. Ese salto es la decisión.","Casi ninguna oferta se acepta o se rechaza completa: se acepta con condiciones, y la condición sale del número. Se decide al día siguiente, nunca con alguien enfrente esperando una firma."];

const critErrorBank=[{"txt":"\"Son 24 cuotas de 1.150 y no cobran intereses, así que sale igual que de contado\".","g1":"Sale 27.600 en total, y la misma laptop al contado cuesta 20.000: el «sin intereses» costó 7.600 lempiras, un 38% sobre el precio, escondido dentro del precio de lista.","g2":"Cuando el interés no se nombra, se cobra por dentro del precio. Sin el precio de contado escrito al lado no hay tasa que calcular ni oferta que comparar."},{"txt":"\"Las dos son al 2% mensual, así que da igual con cuál me quede\".","g1":"No da igual: sobre saldos son 1.560 de intereses y sobre el monto 2.880, o sea 1.320 lempiras de diferencia por el mismo dinero y el mismo plazo.","g2":"Y la primera cuota es 1.240 en las dos, así que el recibo del primer mes no distingue nada. Las cinco palabras que hay que decir siempre son: ¿sobre saldos o sobre el monto?"},{"txt":"\"La cuota de 1.240 cabe en el mes, la pagamos con lo que entra de las aulas\".","g1":"La cuota es un costo fijo nuevo: los fijos pasan de 750 a 1.990 y el punto de equilibrio, de ocho aulas a veinte. Hoy hay seis.","g2":"La deuda no se paga con lo que el proyecto gana hoy, sino con aulas que todavía no existen. El equilibrio se rehace antes de firmar, nunca después."},{"txt":"\"Nos aprobaron 20.000, con eso compramos el equipo completo\".","g1":"A la cuenta llegan 18.750, porque antes se descuentan 600 de comisión, 400 de seguro y 250 de gastos. Y los intereses se cobran sobre 20.000.","g2":"El monto aprobado es publicidad; el desembolsado es el préstamo. Se pide por lo que hace falta más los descuentos, para que lo que llegue alcance."},{"txt":"\"Mejor a 24 meses, así la cuota es de 740 y respiramos\".","g1":"El alivio es real: 500 lempiras menos al mes. El precio también: los intereses pasan de 1.560 a 3.000, o sea 1.440 lempiras por doce meses más atado.","g2":"El plazo reparte, no abarata. Se acepta si el aire sirve para cambiar la situación, no si solo hace el mes más cómodo."},{"txt":"\"Este mes no pagamos y el otro nos ponemos al día, total es una sola cuota\".","g1":"A los tres meses no se deben 3.720 sino cerca de 4.570, entre recargos de 200 por cuota y 5% mensual sobre lo vencido, y el historial queda dañado.","g2":"La mora es una deuda nueva encima de la vieja. Antes de dejar de pagar se llama y se pide reprogramar por escrito, y se pide antes del vencimiento, no después."}];

const critDecisionBank=["La laptop en 24 cuotas de 1.150 «sin intereses», con precio de contado de 20.000: ¿se compra a cuotas o se busca el dinero aparte?","Dos ofertas al 2% mensual por 12.000 a doce meses, una sobre saldos y otra sobre el monto: ¿cómo se distingue cuál es cuál antes de firmar?","Un préstamo con cuota de 1.240 cuando los fijos son 750 y hay seis aulas pagando: ¿se firma, y con qué condición?","Un desembolso de 18.750 sobre 20.000 aprobados: ¿por cuánto se pide el préstamo y qué se pregunta del seguro de deuda?","15.000 para una laptop que produce dos misiones más al mes contra 15.000 para tapar el mes que no alcanzó: ¿cuál se pide y cuál no?","Tres meses de atraso sobre cuotas de 1.240, con recargos y mora corriendo: ¿qué se hace primero y qué se pide por escrito?","La refinanciación que baja la cuota de 1.240 a 740 y sube los intereses 1.440: ¿cuándo vale la pena aceptarla?","El adelanto de 10.000 del patrocinador a cambio de dos años de logo en vez de uno: ¿es deuda, y con qué condición se acepta?"];
const critDecisionGuide="La decisión correcta sigue las reglas de la casa: se firma el total en lempiras y no la cuota; se pregunta siempre si el interés es sobre saldos o sobre el monto; se recuerda que el plazo reparte y no abarata; se anota la cuota como costo fijo y se rehace el punto de equilibrio antes de firmar; y solo se debe por algo que meta más de lo que el interés saca, con margen y no justo. Cuando la oferta es buena y hay prisa, la respuesta es siempre la misma: el total por escrito hoy y la firma mañana.";

const critCompareBank=[{"a":"Firmar mirando la cuota: 740 al mes cabe cómodo.","b":"Firmar mirando el total: 15.000 devueltos por 12.000 prestados.","ga":"Caso A: la decisión se toma con la cifra que el vendedor eligió enseñar, y el precio del dinero nunca llega a discutirse.","gb":"Caso B: la decisión se toma con la única cifra que compara ofertas, y de paso aparece que doce meses más cuestan 1.440 lempiras."},{"a":"Pedir 12.000 a doce meses con cuota de 1.240.","b":"Pedir 12.000 a veinticuatro meses con cuota de 740.","ga":"Caso A: aprieta más cada mes y se sale con 1.560 de intereses y la libertad de vuelta en un año.","gb":"Caso B: respira mejor cada mes y cuesta 3.000 de intereses y dos años sin poder decir que no a un trabajo que no conviene."},{"a":"Pedir prestado para una laptop que permite dos misiones más al mes.","b":"Pedir prestado para cubrir el mes en que no alcanzó.","ga":"Caso A: la deuda compra algo que mete, así que puede pagarse sola si el ingreso ya existe y no solo está prometido.","gb":"Caso B: la deuda no compra nada; mueve el hueco tres meses adelante y lo devuelve con intereses encima."},{"a":"Avisar antes del vencimiento y pedir reprogramar por escrito.","b":"Dejar pasar tres meses y ponerse al día después.","ga":"Caso A: casi siempre existe la opción, casi nunca la ofrecen, y pedirla a tiempo mantiene el historial intacto.","gb":"Caso B: 3.720 de cuotas se vuelven cerca de 4.570 entre recargos y mora, y el crédito siguiente sale más caro o no sale."}];

const critCauseBank=[{"cause":"Se decide mirando la cuota y no el costo total.","guide":"Se firma con la cifra que el que presta eligió enseñar. La cuota baja sola con solo alargar el plazo, así que no dice nada sobre el precio del dinero."},{"cause":"No se pregunta si la tasa es sobre saldos o sobre el monto.","guide":"La misma tasa puede costar casi el doble. Y como la primera cuota es idéntica en los dos casos, el error no se nota hasta el final del préstamo."},{"cause":"Se toma el monto aprobado como si fuera el monto recibido.","guide":"Las comisiones, el seguro y los gastos se descuentan antes del desembolso, así que llega menos de lo que hace falta y se pagan intereses por dinero que nunca se tuvo."},{"cause":"No se rehace el punto de equilibrio con la cuota dentro.","guide":"La cuota es un costo fijo nuevo y mueve el equilibrio de golpe. Firmar sin esa cuenta es apostar a un volumen de aulas que todavía no existe."},{"cause":"Se deja de pagar sin avisar.","guide":"La mora no es proporcional: es una deuda nueva encima de la vieja, con recargo fijo más interés sobre lo vencido, y encima daña el crédito siguiente."},{"cause":"Se pide prestado para tapar un mes que no alcanzó.","guide":"La deuda no compra nada que meta dinero: alquila el hueco por unos meses y lo devuelve con intereses. La salida es recortar o cobrar antes."}];
const critEffectBank=[{"effect":"Se eligió la oferta correcta entre dos que sonaban idénticas.","guide":"Se preguntó si el interés era sobre saldos o sobre el monto antes de mirar la cuota, y esas cinco palabras ahorraron 1.320 lempiras."},{"effect":"El préstamo alcanzó justo para comprar lo que se iba a comprar.","guide":"Se pidió por el monto necesario más los descuentos, sabiendo que de 20.000 aprobados llegan 18.750 a la cuenta."},{"effect":"Se dijo que no a una cuota que cabía cómoda en el mes.","guide":"Se rehizo el punto de equilibrio con la cuota dentro: pasaba de ocho aulas a veinte y solo había seis. El número decidió, no la comodidad."},{"effect":"La deuda se pagó tres meses antes y costó menos de lo previsto.","guide":"Se abonó a capital en cuanto sobró dinero, y como el interés se cobraba sobre saldos, cada abono borró los intereses de los meses que faltaban."},{"effect":"Un mes malo no se convirtió en una bola de nieve.","guide":"Se avisó antes del vencimiento y se pidió la reprogramación por escrito, así que no hubo recargos ni interés de mora ni historial dañado."},{"effect":"El adelanto del patrocinador acabó siendo un buen ingreso.","guide":"Se cotizó el segundo año al precio de ese año y se dejó escrito qué no incluye el patrocinio. Con esas dos líneas dejó de ser una hipoteca sobre la marca."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 El contrato antes de firmar · Forma ${cf} · La deuda por dentro · Ruta del Poder`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. La oferta sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Qué falta preguntar, cuánto se devuelve en total y con qué condición por escrito lo firmarías? Explica por qué tu salida es mejor que aceptar la cuota que te ofrecen o que rechazar de plano.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuánto cuesta cada caso en total y cuál deja al proyecto más libre el año que viene? 2. ¿Por qué no son la misma decisión?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 El contrato antes de firmar: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. La oferta sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Qué falta preguntar, cuánto se devuelve en total y con qué condición por escrito lo firmarías? Explica por qué tu salida es mejor que aceptar la cuota que te ofrecen o que rechazar de plano.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuánto cuesta cada caso en total y cuál deja al proyecto más libre el año que viene? 2. ¿Por qué no son la misma decisión?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>El contrato antes de firmar La deuda por dentro · Ruta del Poder · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · El contrato antes de firmar · La deuda por dentro · Ruta del Poder · Etapa 3 · Poder Económico</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: El contrato antes de firmar · La deuda por dentro · Ruta del Poder · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"💵","label":"El capital","text":"El dinero prestado, y en concreto <strong>el que llega a la cuenta</strong>. <strong>Se mide:</strong> en lempiras desembolsados, no aprobados. <strong>Engaña:</strong> cuando se toma el monto de la carta de aprobación. <strong>En M.E.T.A.S:</strong> de 20.000 aprobados llegan 18.750."},{"y":"2","icon":"📈","label":"La tasa","text":"El precio del dinero por unidad de tiempo. <strong>Se mide:</strong> en porcentaje mensual o anual. <strong>Engaña:</strong> cuando no se dice <strong>sobre qué</strong> se aplica. <strong>En M.E.T.A.S:</strong> el mismo 2% da 1.560 sobre saldos y 2.880 sobre el monto."},{"y":"3","icon":"📅","label":"El plazo","text":"Los meses que dura la deuda. <strong>Se mide:</strong> en número de cuotas. <strong>Engaña:</strong> porque baja la cuota y por eso parece que abarata. <strong>En M.E.T.A.S:</strong> de 12 a 24 meses la cuota baja 500 y el total sube 1.440."},{"y":"4","icon":"🧾","label":"La cuota","text":"Capital <strong>más</strong> interés, cada mes. <strong>Se mide:</strong> en lempiras y con fecha de vencimiento. <strong>Engaña:</strong> porque es la cifra cómoda y la que se compara con el sueldo. <strong>En M.E.T.A.S:</strong> 1.240 el primer mes, y es un costo fijo nuevo."},{"y":"5","icon":"✂️","label":"Comisiones y seguro","text":"Lo que se descuenta <strong>antes</strong> de recibir. <strong>Se mide:</strong> sumando todo en lempiras, no en porcentajes sueltos. <strong>Engaña:</strong> porque no aparece en la cuota. <strong>En M.E.T.A.S:</strong> 600 de comisión, 400 de seguro y 250 de gastos."},{"y":"6","icon":"🧮","label":"El costo total","text":"Cuotas por meses, más gastos, <strong>menos lo que llegó</strong>. <strong>Se mide:</strong> en lempiras, una sola cifra. <strong>Engaña:</strong> cuando nadie la calcula porque nadie la pide. <strong>En M.E.T.A.S:</strong> 13.560 devueltos por 12.000 prestados."},{"y":"7","icon":"⏰","label":"La mora","text":"Lo que se cobra por pagar tarde. <strong>Se mide:</strong> recargo fijo más interés sobre lo vencido. <strong>Engaña:</strong> porque parece proporcional y crece más rápido que la deuda. <strong>En M.E.T.A.S:</strong> tres meses de atraso vuelven 3.720 en unos 4.570."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(conInternet){sfx(conInternet?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(conInternet){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🧮</span><span class="ms-text"><strong>Pediste los dos totales:</strong> 13.560 a doce meses y 15.000 a veinticuatro. La conversación pasa de la cuota al precio del dinero.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📄</span><span class="ms-text"><strong>Y ahora decides tú:</strong> si los 500 al mes de alivio valen 1.440 lempiras, se firma el plazo largo a propósito. Si no, se firma el corto y se acabó.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">✍️</span><span class="ms-text"><strong>Firmaste por la cuota:</strong> cabía en el mes, y esa fue toda la cuenta que se hizo.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🕰️</span><span class="ms-text"><strong>Y el total llega igual:</strong> 1.440 lempiras más y doce meses más atado. No fue un engaño: fue una decisión tomada con la única cifra que te enseñaron.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"capital":{"nombre":"El capital","icon":"💵","estructura":{"title":"Qué es","info":"• El dinero prestado, y solo <strong>el que llegó a la cuenta</strong><br>• Es la parte de la cuota que baja la deuda de verdad<br>• Lo demás que se paga cada mes es precio, no deuda"},"funcion":{"title":"Cómo se calcula","info":"• Monto aprobado <strong>menos</strong> comisiones, seguro y gastos<br>• Se comprueba con el comprobante de depósito, no con la carta<br>• El saldo de capital es lo que queda por devolver en cualquier mes"},"enfermedades":{"title":"Dónde engaña","info":"• Cuando se toma el monto aprobado como si fuera el recibido<br>• Cuando los intereses se calculan sobre el aprobado y no sobre el recibido<br>• Cuando se pide justo lo que hace falta y llega menos"},"cuidados":{"title":"Los números de M.E.T.A.S","info":"• Aprobado: <strong>20.000</strong><br>• Comisión 3%: <strong>600</strong> · Seguro: <strong>400</strong> · Gastos: <strong>250</strong><br>• Llega a la cuenta: <strong>18.750</strong><br>• Y los intereses corren sobre 20.000"}},"tasa":{"nombre":"La tasa","icon":"📈","estructura":{"title":"Qué es","info":"• El precio de usar dinero ajeno durante un tiempo<br>• No es un abuso: es un precio, y como todo precio se compara<br>• Sola no dice nada: hace falta saber <strong>sobre qué se aplica</strong>"},"funcion":{"title":"Cómo se calcula","info":"• <strong>Sobre saldos:</strong> el porcentaje del mes sobre lo que aún se debe<br>• <strong>Sobre el monto:</strong> el porcentaje siempre sobre el préstamo original<br>• Regla del doble: la plana cuesta casi el doble que la de saldos"},"enfermedades":{"title":"Dónde engaña","info":"• En que la <strong>primera cuota es idéntica</strong> en las dos formas<br>• En las tasas mensuales, que suenan pequeñas y se multiplican por doce<br>• En el «cero interés», que se cobra por dentro del precio"},"cuidados":{"title":"Los números de M.E.T.A.S","info":"• 12.000 a doce meses al 2% mensual<br>• Sobre saldos: <strong>1.560</strong> de intereses<br>• Sobre el monto: <strong>2.880</strong><br>• Diferencia por no preguntar: <strong>1.320</strong>"}},"plazo":{"nombre":"El plazo","icon":"📅","estructura":{"title":"Qué es","info":"• Los meses durante los que se debe<br>• Es la palanca que usa el que vende para hacer caber la cuota<br>• <strong>Reparte, no abarata:</strong> más meses son más meses de interés"},"funcion":{"title":"Cómo se calcula","info":"• Se elige el <strong>plazo más corto que el mes aguante</strong><br>• Se comprueba con el total, no con la cuota<br>• Cada año extra tiene un precio que se puede decir en lempiras"},"enfermedades":{"title":"Dónde engaña","info":"• Cuando se ofrece «bajar la cuota» sin decir cuánto sube el total<br>• Cuando la refinanciación se presenta como un favor<br>• Cuando el plazo dura más que la vida útil de lo que se compró"},"cuidados":{"title":"Los números de M.E.T.A.S","info":"• 12 meses: cuota <strong>1.240</strong> · total <strong>13.560</strong><br>• 24 meses: cuota <strong>740</strong> · total <strong>15.000</strong><br>• 36 meses: cuota <strong>573</strong> · total <strong>16.440</strong><br>• Cada año extra: <strong>1.440</strong> más"}},"total":{"nombre":"El costo total","icon":"🧮","estructura":{"title":"Qué es","info":"• Todo lo que se devuelve, <strong>menos lo que se recibió</strong><br>• Es la única cifra que compara dos ofertas distintas<br>• Se dice en lempiras y en voz alta antes de firmar"},"funcion":{"title":"Cómo se calcula","info":"• Cuota <strong>por</strong> número de cuotas<br>• <strong>Más</strong> comisiones, seguro y gastos<br>• <strong>Menos</strong> lo que llegó de verdad a la cuenta"},"enfermedades":{"title":"Dónde engaña","info":"• Cuando nadie lo calcula porque nadie lo pide<br>• Cuando se compara con otra oferta usando la cuota en su lugar<br>• Cuando se olvida que la cuota es un costo fijo nuevo del mes"},"cuidados":{"title":"Los números de M.E.T.A.S","info":"• Devuelto: <strong>13.560</strong> por 12.000 prestados<br>• Fijos con la cuota dentro: <strong>1.990</strong> al mes<br>• Equilibrio: de <strong>8 aulas a 20</strong><br>• Aulas de hoy: <strong>6</strong>"}}};
let labParte='capital',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente gestor en formación!','¡Sabes por dónde se mueve esto!','¡Estratega institucional!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='💳 ¡'+name+' completó la Etapa 3 de la Ruta del Poder (La deuda por dentro)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

